public class WaterRemapTest{
 public static void main(String[]args){var g=new TerrainGraph();var land=g.add(TerrainGraph.Type.CONSTANT,0,0);land.values.put("height",100.0);var lake=g.add(TerrainGraph.Type.LAKE,0,0);lake.values.put("random",0.0);lake.values.put("natural",0.0);lake.values.put("level",120.0);lake.values.put("overflow",0.0);g.connect(land.id,lake.id,0);var remap=g.add(TerrainGraph.Type.REMAP,0,0);remap.values.put("scale",2.0);remap.values.put("offset",-62.0);remap.values.put("water",1.0);g.connect(lake.id,remap.id,0);var result=g.evaluate(64,64,62,42,remap.id,()->false);if(result.environment().water[32*64+32]!=116)throw new AssertionError("water did not scale around sea level");if(result.environment().water[0]!=62)throw new AssertionError("sea level changed");System.out.println("PASS: elevated lake water scales with remapped terrain while sea level stays fixed");}
}
